def solve(X,y):
 X,y=np.asarray(X,float),np.asarray(y,float)
 if X.ndim!=2 or y.shape!=(len(X),): raise ValueError("shape")
 A=np.c_[np.ones(len(X)),X]; G=A.T@A
 return np.linalg.solve(G,A.T@y) if np.linalg.matrix_rank(G)==G.shape[0] else np.linalg.lstsq(A,y,rcond=None)[0]

